import {GamepadHub,padAxis,padButton} from '../3d/index.js';
export function bowlingInput({getState,aim,throwBall,pause,help,getPads=()=>navigator.getGamepads?.()||[]}){let charge=0,wasTrigger=false,keyboardCharge=false;const hub=new GamepadHub({players:2,onDisconnect(){reset();pause('Controller disconnected. Reconnect, then Resume.');}}),keys=new Set();function reset(){keys.clear();charge=0;wasTrigger=false;keyboardCharge=false;hub.clear();}
 const down=e=>{const s=getState();if(!s.active||s.camera||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(['ArrowLeft','ArrowRight','Space','Escape'].includes(e.code)){e.preventDefault();if(e.code==='Escape')pause();else{keys.add(e.code);if(e.code==='Space')keyboardCharge=true;}}};const up=e=>{const s=getState();keys.delete(e.code);if(e.code==='Space'&&keyboardCharge){keyboardCharge=false;if(s.active&&!s.camera)throwBall(charge||.65,'touch');charge=0;}};window.addEventListener('keydown',down);window.addEventListener('keyup',up);
 return{hub,reset,update(dt){const s=getState();hub.poll(getPads(),s.active?'play':'menus');if(!s.active){charge=0;return;}const owner=hub.pad(s.owner)?s.owner:hub.slots.findIndex(slot=>slot),pad=hub.pad(owner);if(hub.pressed(owner,9)){pause();return;}if(hub.pressed(owner,8)){help();return;}if(s.camera)return;const move=(keys.has('ArrowRight')?1:0)-(keys.has('ArrowLeft')?1:0)+(s.controller?padAxis(pad,0):0);if(move)aim(move*dt*.85);const trigger=s.controller&&padButton(pad,7);if(keyboardCharge||trigger)charge=Math.min(1,charge+dt*.65);if(wasTrigger&&!trigger&&s.controller){throwBall(Math.max(.2,charge),'controller');charge=0;}if(s.controller&&hub.pressed(owner,0))throwBall(.65,'controller');wasTrigger=trigger;},get charge(){return charge;},dispose(){reset();hub.dispose();window.removeEventListener('keydown',down);window.removeEventListener('keyup',up);}};
}
